structureCode.vanilla:
import {
  createAlert,
  createAlertIcon,
  createAlertTitle,
  createAlertDescription,
} from '@/components/ui/alert';

const alert = createAlert({ variant: 'info', role: 'status' });        // Container — role por prop (alert | status | note)
alert.appendChild(createAlertIcon('info'));                            // Ícone (opcional, aria-hidden)
alert.appendChild(createAlertTitle({ text: 'Título', as: 'h4' }));  // Título (opcional) — nível pela hierarquia
alert.appendChild(createAlertDescription({ text: 'Descrição' }));      // Descrição

customizationCode.web:
/* As vars internas são declaradas no próprio .nds-alert, então o
   override precisa ser escopado — no :root ele não vence. */
.meu-tema .nds-alert {
  --alert-bg: hsl(var(--card));
  --alert-bg-alpha: 0.15;              /* opacidade da lavagem */
  --alert-border-alpha: 0.35;          /* a borda anda junto com ela */
  --alert-border: hsl(var(--primary) / 0.3);
  --alert-fg: hsl(var(--foreground));
  --alert-body-fg: hsl(var(--foreground));
  --alert-glow: hsl(var(--primary));   /* tom base do gradiente — sem alfa */
}

